import{z as i,x as o,o as B,c as p,q as l,j as n,D as e,d as A,s as r,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"开放经济会计与经常账户","description":"","frontmatter":{"title":"开放经济会计与经常账户","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/open-ca.md","filePath":"econ/open-ca.md","lastUpdated":1791413859000}'),C={name:"econ/open-ca.md"};function d(D,E,m,F,S,u){const t=o("Mermaid");return B(),p("div",null,[E[2]||(E[2]=l('<h1 id="开放经济会计与经常账户" tabindex="-1">开放经济会计与经常账户 <a class="header-anchor" href="#开放经济会计与经常账户" aria-label="Permalink to &quot;开放经济会计与经常账户&quot;">​</a></h1><div class="epigraph"><p>经常账户不是「竞争力评分」，而是国民储蓄减去国内投资：吸收与产出的差，对应对外净要求权的积累。</p><footer>—— 据 SNA 国外账户；对照 Mundell 把外部平衡写成宏观约束之前的会计身份</footer></div><p><a href="/econ/automatic-stabilizers">上一课</a>（自动稳定器）。在封闭或未写国境的装置里谈乘数。支出恒等里一直有 \\(NX\\)，<a href="/econ/saving-investment-id">储蓄–投资</a>用它当代理。本课的缺口是把对外账户写全：经常账户 \\(CA\\)、资本与金融账户、储备，以及 GDP 与 GNI 的差。购买力平价再下一课才给相对价格；本课先保证符号是账，不是蒙代尔图上的斜率。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>封闭时 \\(S=I\\)。开放时国民储蓄可以离开本国资本形成，变成对国外的净债权。缺口是</p> \\[CA \\equiv S-I, \\]<p>在 SNA 口径下与货物服务净出口、要素净收入、经常转移一致（细节科目以手册为准）。\\(CA\\gt 0\\) 是本国吸收 \\(C+I+G\\) 小于国民收入，不是道德上的「盈余美德」。财政课的孪生赤字是这句恒等的部门展开：公共 \\(S^g\\) 下降，若私人 \\(S^p-I\\) 不变，则 \\(CA\\) 下降。</p><p><span class="marginnote">直觉类比：把国家想成一个家庭，\\(S-I\\) 就是「这个家攒下的钱减去花在自家房子上的装修」。攒得多、修得少，余钱借给了别人（对外净债权）；攒得少、修得多，就得向别人借钱。\\(CA\\) 记录的正是这个差，不是「竞争力考卷」的分数。</span></p><p>GDP 课留下的国内与国民之差，在此落地：GNI $= $ GDP \\(+\\) 跨境要素净收入。\\(CA\\) 用国民口径更干净。本课不把 \\(CA\\) 写成汇率的函数——那是 PPP 与蒙代尔。</p><p><span class="marginnote">金融账户记录谁向谁买了哪些资产。经常账户与金融账户（加储备与净误差）对平。恒等不告诉你资本流入是「推动」还是「拉动」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>支出：\\(Y=C+I+G+NX_{\\mathrm{goods,services}}\\)。国民收入再调要素与转移。跨期：一国的 \\(CA\\) 是对未来净出口的要求权变化，欧拉在开放下变成对外净资产的平滑——Obstfeld 一类跨期方法，本课只借用：赤字可以是最优的投资高峰或平滑消费，不必是失衡的同义词。</p>',12)),(B(),n(s,null,{default:e(()=>[r(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%9B%BD%E6%B0%91%E5%82%A8%E8%93%84%20S%22%5D%20--%3E%20CA%5B%22CA%20%3D%20S%E2%88%92I%22%5D%0A%20%20I%5B%22%E5%9B%BD%E5%86%85%E6%8A%95%E8%B5%84%20I%22%5D%20--%3E%20CA%0A%20%20CA%20--%3E%20NFA%5B%22%E5%AF%B9%E5%A4%96%E5%87%80%E8%B5%84%E4%BA%A7%E5%8F%98%E5%8C%96%22%5D%0A%20%20NX%5B%22%E5%87%80%E5%87%BA%E5%8F%A3%E4%B8%8E%E8%A6%81%E7%B4%A0%E8%BD%AC%E7%A7%BB%22%5D%20--%3E%20CA%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"储备与汇率制度：央行买外汇，金融账户与储备同时动，经常账户仍由 \\(S-I\\) 决定。不可能三角会把「资本自由流动」写成这一金融账户的开放度；本课只记下账户存在。",-1)),E[4]||(E[4]=a("h3",{id:"乘数的开放漏出",tabindex:"-1"},[A("乘数的开放漏出 "),a("a",{class:"header-anchor",href:"#乘数的开放漏出","aria-label":'Permalink to "乘数的开放漏出"'},"​")],-1)),E[5]||(E[5]=a("p",null,"\\(G\\) 上升提高吸收，一部分变成进口，\\(CA\\) 变差，封闭乘数缩小。李嘉图与欧拉仍适用：若减税被对外借贷平滑，对外净资产下降，未来要用净出口偿还。批判仍在：开放度与汇率规则都进简化式。",-1)),E[6]||(E[6]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[7]||(E[7]=a("p",null,[A("每一笔未用于国内 \\(C+I+G\\) 的国民产出，变成对国外的净要求权；反过来，吸收超过产出就消耗对外资产或增加对外负债。汇率、利率、相对价格决定的是"),a("strong",null,"均衡中"),A(" \\(S\\)、\\(I\\) 如何调整，不是恒等是否成立。货币中性的长期：名义汇率可以变，\\(CA\\) 的实物路径由跨期偏好、投资机会与净国外资产决定。")],-1)),(B(),n(s,null,{default:e(()=>[r(t,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%90%B8%E6%94%B6%E8%B6%85%E8%BF%87%E4%BA%A7%E5%87%BA%EF%BC%9A%E8%BF%9B%E5%8F%A3%E5%A4%9A%E4%BA%8E%E5%87%BA%E5%8F%A3%22%5D%20--%3E%20D%5B%22%E7%BB%8F%E5%B8%B8%E8%B4%A6%E6%88%B7%E9%80%86%E5%B7%AE%EF%BC%9ACA%20%E4%B8%BA%E8%B4%9F%22%5D%0A%20%20D%20--%3E%20Q%7B%22%E7%BC%BA%E5%8F%A3%E7%94%A8%E4%BB%80%E4%B9%88%E8%A1%A5%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%90%91%E5%A4%96%E5%9B%BD%E4%BA%BA%E5%8D%96%E8%B5%84%E4%BA%A7%E3%80%81%E5%8F%91%E5%80%BA%22%7C%20FA%5B%22%E9%87%91%E8%9E%8D%E8%B4%A6%E6%88%B7%EF%BC%9A%E8%B5%84%E6%9C%AC%E5%87%80%E6%B5%81%E5%85%A5%22%5D%0A%20%20Q%20--%3E%7C%22%E5%8A%A8%E7%94%A8%E5%A4%96%E6%B1%87%E5%82%A8%E5%A4%87%22%7C%20RES%5B%22%E5%A4%AE%E8%A1%8C%E5%82%A8%E5%A4%87%E4%B8%8B%E9%99%8D%22%5D%0A%20%20FA%20--%3E%20BAL%5B%22%E8%B4%A6%E7%B0%BF%E5%AF%B9%E5%B9%B3%EF%BC%9A%E9%87%91%E8%9E%8D%E8%B4%A6%E6%88%B7%E4%B8%8E%E5%82%A8%E5%A4%87%E4%B9%8B%E5%92%8C%20%3D%20%E8%B4%9F%E7%9A%84%20CA%22%5D%0A%20%20RES%20--%3E%20BAL%0A%20%20BAL%20--%3E%20FUT%5B%22%E5%B0%86%E6%9D%A5%EF%BC%9A%E7%94%A8%E5%87%80%E5%87%BA%E5%8F%A3%E4%B8%8E%E8%A6%81%E7%B4%A0%E6%94%B6%E5%85%A5%E5%81%BF%E8%BF%98%EF%BC%8C%E5%AF%B9%E5%A4%96%E5%87%80%E8%B5%84%E4%BA%A7%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=l('<p><span class="marginnote">数字实例：GDP 为 100、吸收 \\(A=C+I+G=103\\)，则 \\(CA=-3\\)——本国多花掉的 3 块钱，对应对外净资产减少 3 块。若明年 GDP 涨到 105 而 \\(A\\) 仍是 103，\\(CA\\) 转正为 2，正好开始「还账」。</span></p><p>财政扩张在浮动与固定下对 \\(CA\\) 的短期效应不同，那是蒙代尔–弗莱明。会计先行：无论哪一种，\\(S-I\\) 必须等于 \\(CA\\)。</p><p>吸收法：\\(CA=Y-A\\)，\\(A=C+I+G\\)。贬值要改善 \\(CA\\)，必须 \\(Y\\) 升或 \\(A\\) 降。这是会计加一句行为空位。GDP 与 GNI 的差在跨境要素落地。孪生赤字是恒等的部门展开，不是因果。</p><p><span class="marginnote">BPM 把直接投资、组合、其他、储备写在金融账户。本课用「资本流动」作口语，与科目名不完全同义。恒等不告诉你流入是推动还是拉动。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把双边贸易差额当成福利。不要把统计误差当理论。量化栏的外汇微观结构、CIP 偏差，不是 SNA 科目；本栏加总到宏观净额为止。公司如何在境外融资，留给资本结构课。发展中经济的 \\(CA\\) 逆差可以是 \\(I\\) 高，不是 \\(S\\) 不道德。</p><p><span class="marginnote">常见误区：听到「贸易逆差」就想到「输给了外国」。会计上逆差只说明吸收大于产出，可能正值国内投资高峰、借钱搞建设；顺差也可能是消费不足、钱被迫外借。恒等本身不含因果与好坏，判断要回到 \\(S\\) 与 \\(I\\) 各自为什么在动。</span></p><p>后课默认：写下开放宏观时，\\(CA=S-I\\) 是恒等，事前均衡另说。下一课先看双赤字如何落在这条恒等上；再下一课用一价定律与购买力平价给相对价格与汇率一个长期锚。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(CA=S-I\\) 是国外账户恒等，不是竞争力排名。</li><li>GDP 与 GNI 差在跨境要素；经常账户含净出口、要素、转移。</li><li>跨期上赤字可以是平滑或投资，不必等于「失衡」。</li><li>吸收法把 \\(CA\\) 写成产出减吸收，行为仍空着。</li><li>汇率制度改变的是调整渠道，不是恒等。</li><li>出处：SNA 国外账户；IMF BPM。</li></ul>',10))])}const c=i(C,[["render",d]]);export{h as __pageData,c as default};
